program.source:
Subroutine Intercambiar(a As Integer, b As Integer)
  Define guardado As Integer <- a;
  a <- b;
  b <- guardado;
EndSubroutine

Algorithm Principal
  Define primero, segundo As Integer;
  Read primero;
  Read segundo;
  Intercambiar(primero, segundo);
  Write primero, " ", segundo;
EndAlgorithm

